<?php
/*
 * Database settings of the Medical Map module.
 * These are the XAMPP defaults on Windows (user "root", empty password).
 *
 * If your MySQL uses another user or a password (common on Linux and macOS),
 * do NOT edit this file. Copy database.local.example.php to database.local.php
 * and put your own values there: that file stays on your machine (Git ignores it).
 */
$config = [
    'host' => '127.0.0.1',
    'port' => 3306,
    'dbname' => 'saha_plus',
    'user' => 'root',
    'password' => '',
    'charset' => 'utf8mb4',
];

// Personal settings of this machine, if any, replace the defaults above.
$localFile = __DIR__ . '/database.local.php';
if (is_file($localFile)) {
    $config = array_merge($config, require $localFile);
}

return $config;
